#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
using namespace std;

int main(){
vector<double>x={1,2,3,4,5},y={1,1,2,5,6};double best=1e100,threshold=0;
for(int cut=1;cut<int(x.size());cut++){double left=0,right=0,loss=0;for(int i=0;i<cut;i++)left+=y[i]/cut;for(int i=cut;i<int(x.size());i++)right+=y[i]/(x.size()-cut);
for(int i=0;i<int(x.size());i++)loss+=pow(y[i]-(i<cut?left:right),2);
if(loss<best){best=loss;threshold=(x[cut-1]+x[cut])/2;}}
cout<<threshold<<" "<<best<<"\n";
return 0;
}

