#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
using namespace std;

int main(){
double x=1,p=0.7,step=0.15;int steps=5;
auto potential=[](double z){return 0.5*z*z;};
auto derivative=[](double z){return z;};
double initial=potential(x)+0.5*p*p;
p-=0.5*step*derivative(x);
for(int i=0;i<steps;i++){x+=step*p;if(i+1<steps)p-=step*derivative(x);}
p-=0.5*step*derivative(x);
cout<<"initial H "<<initial<<" final H "<<potential(x)+0.5*p*p<<"\n";
return 0;
}

